from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); enclosed=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==1 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); cells=[]; edge=False
   while q:
    x,y=q.pop(); cells.append((x,y)); edge |= x in (0,R-1) or y in (0,C-1)
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and grid[nx][ny]==1 and (nx,ny) not in seen:
      seen.add((nx,ny));q.append((nx,ny))
   if not edge: enclosed.append(cells)
[(len(x), (min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x)), sorted(x)) for x in enclosed]

